input.command:
cd /Users/kristinarash/.claude/jobs/624274f9/tmp/batch-100 && node -e '
const fs=require("fs");const tx=require("./taxonomy.json");
const ids=["Q17","Q18","Q19","Q20","Q21","Q22","Q23","Q24"];
for(const id of ids){
 const raw=fs.readFileSync(`drafts/${id}.json`,"utf8");
 let d; try{d=JSON.parse(raw)}catch(e){console.log(id,"PARSE FAIL",e.message);continue}
 const errs=[];
 if(!["INCLUDE","EXCLUDE","DEGRADED"].includes(d.decision))errs.push("decision");
 if(!tx.studyDesigns.includes(d.studyDesign))errs.push("design:"+d.studyDesign);
 if(!tx.domains.includes(d.primaryDomain))errs.push("primary");
 if(!d.domains.includes(d.primaryDomain))errs.push("primary not in domains");
 for(const x of d.domains)if(!tx.domains.includes(x))errs.push("domain:"+x);
 for(const x of d.audiences)if(!tx.audiences.includes(x))errs.push("aud:"+x);
 for(const x of d.sports)if(!tx.sports.includes(x))errs.push("sport:"+x);
 for(const x of d.populations)if(!tx.populations.includes(x))errs.push("pop:"+x);
 if(/—/.test(raw))errs.push("em dash");
 console.log(id,d.decision,d.studyDesign,d.paper.year,d.paper.doi,errs.length?errs.join("; "):"OK");
}'

